namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, Fresh mozzarella, San Marzano tomatoes, Fresh basil, Olive oil, Salt", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Add torn mozzarella pieces.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook spaghetti in salted water.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, stir in egg mixture.\n6. Serve immediately with extra pecorino.", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Heavy cream, Onion, Garlic, Ginger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and simmer.\n5. Stir in cream and garam masala.\n6. Add chicken pieces and simmer 10 minutes.", AverageRating = 4.7, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Pad Thai", Category = "Asian", Ingredients = "Rice noodles, Shrimp, Eggs, Bean sprouts, Peanuts, Tamarind paste, Fish sauce, Lime", Steps = "1. Soak rice noodles in warm water.\n2. Stir-fry shrimp until pink, set aside.\n3. Scramble eggs in the wok.\n4. Add noodles, tamarind paste, and fish sauce.\n5. Toss with shrimp and bean sprouts.\n6. Serve with crushed peanuts and lime.", AverageRating = 4.3, RatingCount = 8 },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheese, Sour cream, Taco seasoning", Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer.\n3. Warm taco shells in oven.\n4. Fill shells with seasoned beef.\n5. Top with lettuce, tomato, cheese.\n6. Add sour cream and serve.", AverageRating = 4.1, RatingCount = 10 },
        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Red onion, Cilantro, Jalapeño, Tomato, Salt", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Stir in diced onion, tomato, jalapeño.\n4. Add lime juice and cilantro.\n5. Season with salt.\n6. Serve with tortilla chips.", AverageRating = 4.6, RatingCount = 18 },
        new Recipe { Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts", Ingredients = "Butter, Sugar, Brown sugar, Eggs, Vanilla, Flour, Baking soda, Chocolate chips", Steps = "1. Cream butter with sugars.\n2. Beat in eggs and vanilla.\n3. Mix flour, baking soda, and salt.\n4. Combine wet and dry ingredients.\n5. Fold in chocolate chips.\n6. Bake at 375°F for 9-11 minutes.", AverageRating = 4.9, RatingCount = 25 },
        new Recipe { Id = 8, Title = "Miso Soup", Category = "Asian", Ingredients = "Dashi stock, White miso paste, Tofu, Wakame seaweed, Green onions", Steps = "1. Heat dashi stock until simmering.\n2. Dissolve miso paste in a ladle of stock.\n3. Add dissolved miso back to pot.\n4. Add cubed tofu and wakame.\n5. Heat gently (do not boil).\n6. Serve topped with sliced green onions.", AverageRating = 4.2, RatingCount = 6 },
    };

    private readonly Dictionary<int, List<int>> _ratings = new();

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe == null || stars < 1 || stars > 5) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);

        var totalRatings = recipe.RatingCount + _ratings[recipeId].Count;
        var totalScore = (recipe.AverageRating * recipe.RatingCount) + _ratings[recipeId].Sum();
        recipe.AverageRating = Math.Round(totalScore / totalRatings, 1);
        recipe.RatingCount = totalRatings;
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _displayRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => _hoverRating = star"
              @onmouseout="() => _hoverRating = 0">
            ★
        </span>
    }
    <span class="rating-info">(@AverageRating.ToString("0.0") avg, @RatingCount ratings)</span>
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int _hoverRating;
    private int _userRating;
    private bool _submitted;

    private int _displayRating => _hoverRating > 0 ? _hoverRating : _userRating;

    private void Rate(int stars)
    {
        _userRating = stars;
        _submitted = true;
        RecipeService.AddRating(RecipeId, stars);
        var updated = RecipeService.GetRecipeById(RecipeId);
        if (updated != null)
        {
            AverageRating = updated.AverageRating;
            RatingCount = updated.RatingCount;
        }
    }
}

