arguments.file_text:
@page "/"

@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>RecipeShare - Home</PageTitle>

<h1>🍽️ RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2>Browse by Category</h2>
<div class="category-grid">
    @foreach (var category in RecipeService.GetCategories())
    {
        <a href="/category/@category" class="category-card">
            <h3>@GetCategoryEmoji(category) @category</h3>
            <p>@RecipeService.GetRecipesByCategory(category).Count recipes</p>
        </a>
    }
</div>

@code {
    private string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Asian" => "🥢",
        "Mexican" => "🌮",
        "Desserts" => "🍰",
        _ => "🍴"
    };
}

@page "/category/{CategoryName}"

@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (recipes.Any())
{
    <div class="recipe-list">
        @foreach (var recipe in recipes)
        {
            <a href="/recipe/@recipe.Id" class="recipe-card">
                <h3>@recipe.Title</h3>
                <div class="recipe-meta">
                    <span class="stars">@(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))</span>
                    <span>@recipe.AverageRating.ToString("0.0") (@recipe.RatingCount ratings)</span>
                </div>
            </a>
        }
    </div>
}
else
{
    <p>No recipes found in this category.</p>
}

<a href="/">← Back to Categories</a>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private List<RecipeShare.Models.Recipe> recipes = new();

    protected override void OnInitialized()
    {
        recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"

@using RecipeShare.Services
@using RecipeShare.Components.Shared
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (recipe != null)
{
    <h1>@recipe.Title</h1>
    <p class="recipe-category">Category: <a href="/category/@recipe.Category">@recipe.Category</a></p>

    <StarRating RecipeId="@recipe.Id" AverageRating="@recipe.AverageRating" RatingCount="@recipe.RatingCount" />

    <h2>Ingredients</h2>
    <ul class="ingredients-list">
        @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h2>Steps</h2>
    <ol class="steps-list">
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
